&= a_1 \left( x - x^3 - \frac{3}{2} xy(1 - x) \right) + a_2 \left( y - y^3 - \frac{3}{2} xy(1 - x) \right).
\end{align*}If $p(r,s) = 0$ for every such polynomial, then
