r - r^3 - \frac{3}{2} rs (1 - r) &= 0, \\
s - s^3 - \frac{3}{2} rs (1 - r) &= 0.
\end{align*}These factor as
\begin{align*}
\frac{1}{2} r(1 - r)(2r - 3s + 2) &= 0, \\
\frac{1}{2} s(3r^2 - 3r - 2s^2 + 2) &= 0.
\end{align*}Hence, $r = 0,$ $r = 1,$ or $r = \frac{3s - 2}{2}.$

